"""Sandbox sweeper: every 15 minutes, remove sandbox VMs and disks that no live run owns."""
import datetime as dt
import json
import os

import boto3

ec2 = boto3.client("ec2")
DRY_RUN = os.environ.get("DRY_RUN", "true") == "true"
MANAGED = {"Name": "tag:ai-agents:managed", "Values": ["true"]}


def handler(event, context):
    now = dt.datetime.now(dt.UTC)
    swept = 0
    for vm in managed_vms():
        tags = {t["Key"]: t["Value"] for t in vm.get("Tags", [])}
        lease = tags.get("ai-agents:lease-until")
        if "ai-agents:run-id" in tags and (not lease or dt.datetime.fromisoformat(lease) < now):
            act("terminate", vm["InstanceId"], "lease expired: no live run owns this VM")
            swept += 1
    for disk in orphan_disks():
        act("delete-volume", disk["VolumeId"], "disk attached to no VM")
        swept += 1
    return {"swept": swept, "dry_run": DRY_RUN}


def managed_vms():
    pages = ec2.get_paginator("describe_instances").paginate(
        Filters=[MANAGED, {"Name": "instance-state-name", "Values": ["running", "stopped"]}])
    return [vm for page in pages for r in page["Reservations"] for vm in r["Instances"]]


def orphan_disks():
    pages = ec2.get_paginator("describe_volumes").paginate(
        Filters=[MANAGED, {"Name": "status", "Values": ["available"]}])
    return [disk for page in pages for disk in page["Volumes"]]


def act(action, resource_id, reason):
    print(json.dumps({"action": action, "id": resource_id, "reason": reason, "dry_run": DRY_RUN}))
    if DRY_RUN:
        return
    if action == "terminate":
        ec2.terminate_instances(InstanceIds=[resource_id])
    else:
        ec2.delete_volume(VolumeId=resource_id)

# Test disks, then run the sweeper again with DRY_RUN=false:
#   aws ec2 create-volume --availability-zone us-east-1a --size 120 \
#     --tag-specifications 'ResourceType=volume,Tags=[{Key=ai-agents:managed,Value=true}]'
#   aws ec2 create-volume --availability-zone us-east-1a --size 8
# Afterwards describe-volumes no longer lists the tagged 120 GiB disk; the untagged one stays.
